  "Buscar sessões por título, projeto ou conta": "依標題、專案或帳號搜尋工作階段",
  "Sessões recentes": "最近的工作階段",
  "Fechar histórico": "關閉歷史",
  "Últimos 7 dias, de todas as contas. Clique para ler a conversa no terminal.": "最近 7 天，所有帳號。點選即可在終端機閱讀對話。",
  "Histórico de sessões (últimos 7 dias)": "工作階段歷史（最近 7 天）",
  "Histórico de sessões: {0}": "工作階段歷史：{0}",
  "Não foi possível carregar o histórico.": "無法載入歷史。",
  "Não foi possível falar com o servidor.": "無法連線到伺服器。",
  "Carregando as sessões…": "正在載入工作階段……",
  "Nenhuma sessão nos últimos 7 dias.": "最近 7 天沒有工作階段。",
  "Nenhuma sessão encontrada para “{0}”.": "找不到符合「{0}」的工作階段。",
