  "Selecione um agente para abrir o terminal.": "請選擇要開啟終端機的代理人。",

  // client/src/ui/model.ts
  "Concluído": "已完成",
  "Saindo": "離開中",
  "Trabalhando…": "工作中……",
  "Precisa de você: {0}": "需要你：{0}",
  "Esperando o shell terminar": "等待 shell 結束",
  "Concluiu a tarefa": "完成了任務",
  "Saindo do escritório": "正在離開辦公室",
  "Aguardando instruções": "等待指示中",
  "Agente principal": "主代理人",
  "segundo plano": "背景",
  "primeiro plano": "前景",
  "Esperando o comando terminar": "等待指令結束",
  "Está parado num comando no terminal, esperando ele terminar para continuar o turno.": "卡在終端機的一個指令上，等它跑完才能繼續這一輪。",
  "Terminou o turno e está esperando {0} shells terminarem. A cada um que termina, o agente recebe o resultado.": "已結束這一輪，正在等 {0} 個 shell 結束。每結束一個，代理人就會收到結果。",
  "Terminou o turno e está esperando o shell terminar. Quando ele terminar, o agente recebe o resultado.": "已結束這一輪，正在等 shell 結束。結束後，代理人會收到結果。",
  "Comendo pipoca e assistindo ao terminal": "邊吃爆米花邊看終端機",
  "Até 3 min: recosta na cadeira com um balde de pipoca e assiste ao terminal como se fosse um filme.": "最多 3 分鐘：靠著椅背，捧著一桶爆米花，把終端機當電影看。",
  "A pipoca acabou: girando na cadeira": "爆米花吃完了：在椅子上轉圈",
  "De 3 a 10 min: a pipoca acaba; braços cruzados, dedos batendo e, de vez em quando, um giro completo na cadeira.": "3 到 10 分鐘：爆米花吃完了；雙臂交叉、手指敲桌，偶爾還會在椅子上整個轉一圈。",
  "Já tem teia de aranha na cadeira": "椅子上已經結蜘蛛網了",
  "Depois de 10 min: aparece uma teia de aranha na cadeira (ela cresce depois de 20 min) e escapa um bocejo.": "超過 10 分鐘：椅子上出現蜘蛛網（20 分鐘後會變大），還忍不住打了個哈欠。",
  "Cochilou esperando o shell": "等 shell 等到睡著了",
  "Depois de 25 min: cochila na mesa, coberto de teia.": "超過 25 分鐘：趴在桌上打盹，全身蓋滿蜘蛛網。",
  "atalho {0}": "捷徑 {0}",
  "atalhos {0} ou {1}": "捷徑 {0} 或 {1}",

  // client/src/ui/movable.ts
  "Restaurar o tamanho": "還原大小",
  "Expandir na tela toda": "展開為全螢幕",

  // client/src/ui/notify.ts
  "Habblaud — precisa de você": "Habblaud — 需要你",

  // client/src/ui/overlays.ts
  "Conectando ao escritório…": "正在連線到辦公室……",
  "O servidor do Habblaud não responde. Confira se ele está rodando (npm run dev ou npm start); seguimos tentando.": "Habblaud 伺服器沒有回應。請確認它是否正在執行（npm run dev 或 npm start）；我們會持續重試。",
