  "Quando um agente compacta o contexto, a lixeira da sala enche. Sai só o fato, nada do conteúdo.": "代理人壓縮上下文時，房間的垃圾桶會滿起來。只送出「有壓縮」這件事，不含任何內容。",
  "Avisar quando baterem na porta": "有人敲門時通知我",
  "Quem estiver na porta do seu prédio pode bater; o aviso chega aqui no Habblaud, sem o nome de quem bateu.": "站在你大樓門口的人可以敲門；通知會出現在 Habblaud 這裡，不會顯示是誰敲的。",
  "O tema também vale para o seu prédio no Habblaud World.": "主題也會套用到你在 Habblaud World 的大樓。",
  "Não deu para mandar o tema para o prédio: {0}": "無法把主題傳送到大樓：{0}",
