  "Sem conta": "沒有帳號",
  "Na lista de espera": "候補中",
  "Liberado": "已開放",
  "A conta do Habblaud World só pode ser mexida no próprio computador, com o Habblaud em acesso local (bind 127.0.0.1) e aberto por http://localhost.": "Habblaud World 帳號只能在這台電腦上管理，且 Habblaud 需為本機存取（bind 127.0.0.1）並透過 http://localhost 開啟。",
  "Já tenho conta": "我已經有帳號",
  "Leve o seu escritório para uma cidade em pixel art: um prédio seu, aceso enquanto os agentes trabalham, e um personagem para passear e visitar os prédios de outras pessoas.": "把你的辦公室帶進像素風城市：一棟屬於你的大樓，代理人工作時燈會亮著，還有一個角色可以四處散步、參觀別人的大樓。",
  "O acesso é liberado aos poucos: quem cria a conta entra numa lista de espera.": "採分批開放：建立帳號後會先進入候補名單。",
  "O que sai do seu computador": "哪些資料會離開你的電腦",
  "Quem visita o mundo vê, ao vivo, quantos projetos e agentes você está rodando e o que cada personagem está fazendo (trabalhando, esperando, à toa). Ninguém vê quais projetos são, o que os agentes fazem, nem quem você é: só o nickname e o avatar que você escolheu.": "參觀世界的人可以即時看到你正在執行多少專案和代理人，以及每個角色在做什麼（工作中、等待中、閒置）。沒有人看得到是哪些專案、代理人在做什麼，或你是誰：只看得到你選的暱稱和頭像。",
  "Sai:": "會送出：",
  "o tema do escritório; um andar por sala aberta, com um código aleatório que muda todo dia; de cada agente, se é principal ou subagente, a ferramenta, o status, a aparência, um nome sorteado e a faixa de tarefas concluídas no dia; os tokens do prédio arredondados em faixas (dá para desligar); se você ligar, o fato de um agente ter compactado o contexto; a versão e o commit do Habblaud, com a marca de cópia modificada; e o idioma da interface, só para os e-mails.": "辦公室主題；每個開啟的房間一層樓，附上每天更換的隨機代碼；每個代理人是主代理人還是子代理人、使用的工具、狀態、外觀、隨機抽出的名字，以及當天完成任務數的區間；大樓的 token 數（四捨五入為區間，可以關閉）；若你開啟，代理人壓縮了上下文這件事；Habblaud 的版本與建置 commit，以及修改版標記；還有介面語言（只用於電子郵件）。",
  "Nunca sai:": "絕不送出：",
  "caminhos e nomes de projetos, títulos de sessão, comandos, mensagens, código, custo, a sua conta do Claude, o seu e-mail e o nome do computador.": "專案路徑與名稱、工作階段標題、指令、訊息、程式碼、費用、你的 Claude 帳號、你的電子郵件和電腦名稱。",
  "Com os dados que saem não dá para saber quem você é nem em que trabalha.": "從送出的資料無法得知你是誰，也無法得知你在做什麼。",
  "Os agentes trabalham sem você: prédio aceso não quer dizer que você está no computador. Se preferir, use o modo discreto ou feche o prédio a visitas.": "代理人不需要你也能工作：大樓亮燈不代表你在電腦前。如果介意，可以使用低調模式，或讓大樓不開放參觀。",
  "Ver a lista completa": "查看完整清單",
  "Nome de jogador": "玩家名稱",
  "3 a 20 caracteres; é o nome do seu personagem e fica reservado para você, mesmo na lista de espera. Único no mundo.": "3 到 20 個字元；這是你角色的名字，即使在候補名單中也會為你保留。全世界唯一。",
  "Senha": "密碼",
