  "De 3 a 20 caracteres: letras de um só alfabeto, números, espaço, _ - e . É o seu nome no mundo e não pode repetir o de ninguém.": "3 到 20 個字元：單一字母系統的文字、數字、空格、_ - 和 .。這是你在世界中的名字，不能和任何人重複。",
