  "Escolha 2 ou 3 traços. Os que não combinam com os já escolhidos ficam apagados.": "請選 2 或 3 個特質。和已選特質不搭的會變暗。",
  "Aparece no seu perfil, traduzida para quem lê. No mundo não há texto livre além do nome.": "會顯示在你的個人檔案上，並為讀者翻譯。除了名字之外，世界中沒有任何自由輸入的文字。",
