  "Ao vivo: andares, contadores e o que cada personagem está fazendo, em tempo real. Discreto: só aceso ou apagado e o número de andares.": "即時：樓層、計數器以及每個角色正在做什麼，即時呈現。低調：只顯示亮燈或熄燈，以及樓層數。",
