  "Avisar por e-mail antes de retirar meu prédio por inatividade": "因閒置而移除我的大樓之前，先寄電子郵件通知我",
  "Sem notícias deste Habblaud por 7 dias, o prédio some do mapa e, 30 dias depois, é retirado. O e-mail chega 3 dias antes da retirada.": "這個 Habblaud 連續 7 天沒有消息，大樓就會從地圖上消失，30 天後移除。電子郵件會在移除前 3 天寄出。",
  "O aviso de inatividade fica disponível depois de criar o personagem.": "建立角色後才能使用閒置通知。",
  "Baixar meus dados": "下載我的資料",
  "Pronto: o arquivo {0} foi para a pasta de downloads.": "完成：檔案 {0} 已存到你的下載資料夾。",
  "Seus dados": "你的資料",
  "Um arquivo JSON com o que o Habblaud World guarda da sua conta: e-mail, datas, personagem, visibilidade, dispositivos, prédio, likes dados, bloqueios e denúncias feitas. Dá para baixar uma vez por dia.": "一個 JSON 檔案，包含 Habblaud World 保存的帳號資料：電子郵件、日期、角色、能見度、裝置、大樓、送出的讚、封鎖和你提出的檢舉。每天可下載一次。",
  "Excluir conta…": "刪除帳號…",
  "Excluir a conta tira você do Habblaud World:": "刪除帳號會讓你離開 Habblaud World：",
  "Na hora:": "立即：",
  "o prédio e o perfil somem do mundo, e este computador sai da conta.": "大樓和個人檔案會從世界消失，這台電腦也會登出帳號。",
  "Em 7 dias:": "7 天內：",
  "a conta, o personagem, os likes dados e recebidos, os bloqueios, as denúncias feitas e os dispositivos são apagados do banco.": "帳號、角色、送出和收到的讚、封鎖、你提出的檢舉以及裝置，都會從資料庫刪除。",
  "Em até 30 dias:": "30 天內：",
  "somem também dos backups.": "也會從備份中消失。",
  "Se quiser guardar uma cópia, baixe os seus dados antes.": "如果想保留一份副本，請先下載你的資料。",
  "Mandar o código": "寄送驗證碼",
  "Tem certeza? O prédio e o perfil saem do mundo assim que você digitar o código.": "確定嗎？一輸入驗證碼，大樓和個人檔案就會離開世界。",
  "Para confirmar, mandamos um código de 6 dígitos para o e-mail da conta ({0}).": "為了確認，我們會寄 6 位數驗證碼到帳號的電子郵件（{0}）。",
  "Excluir a conta": "刪除帳號",
  "Excluindo…": "刪除中…",
  "Mandamos um código de 6 dígitos para {0}. Digite o código para excluir a conta.": "我們已寄出 6 位數驗證碼到 {0}。輸入驗證碼即可刪除帳號。",
  "Excluir conta": "刪除帳號",

  // scripts/statusline-install.ts
  "Uso: npm run usage:<install|uninstall|status> [-- opções]\n\n  install     envolve o statusline de cada conta com o tap do Habblaud (faz backup do settings.json)\n  uninstall   restaura o statusline original de cada conta\n  status      mostra se o tap está instalado e quando chegou o último uso de cada conta\n\nOpções:\n  --dry-run        mostra o que mudaria, sem gravar nada\n  --node <cmd>     comando do node usado no statusline (padrão: detectado no PATH)\n  -h, --help       mostra esta ajuda\n\nContas: as mesmas do servidor (~/.claude* com projects/ ou sessions/, CLAUDE_CONFIG_DIR ou\nHABBLAUD_CLAUDE_DIRS). Uso capturado em HABBLAUD_USAGE_DIR (padrão ~/.habblaud/usage).": "用法：npm run usage:<install|uninstall|status> [-- 選項]\n\n  install     用 Habblaud 的 tap 包住每個帳號的狀態列（會備份 settings.json）\n  uninstall   還原每個帳號原本的狀態列\n  status      顯示 tap 是否已安裝，以及每個帳號最後一次用量的收到時間\n\n選項：\n  --dry-run        顯示會變更什麼，不寫入任何東西\n  --node <cmd>     狀態列使用的 node 指令（預設：從 PATH 偵測）\n  -h, --help       顯示這份說明\n\n帳號：與伺服器相同（含 projects/ 或 sessions/ 的 ~/.claude*、CLAUDE_CONFIG_DIR 或\nHABBLAUD_CLAUDE_DIRS）。用量記錄在 HABBLAUD_USAGE_DIR（預設 ~/.habblaud/usage）。",
  "statusLine em formato desconhecido; nada foi alterado": "statusLine 格式不明；未做任何變更",
  "sem statusline antes: criado um que só captura o uso (não imprime nada)": "原本沒有狀態列：已建立一個只擷取用量的狀態列（不輸出任何內容）",
  "statusLine do tipo \"{0}\" não é suportado; nada foi alterado": "不支援類型為 \"{0}\" 的 statusLine；未做任何變更",
  "statusLine sem comando; nada foi alterado": "statusLine 沒有指令；未做任何變更",
  "o comando já menciona o tap, mas não no formato esperado; confira à mão": "指令中已經提到 tap，但格式不符預期；請手動檢查",
  "atualizado (novo caminho do Habblaud ou do node)": "已更新（Habblaud 或 node 的路徑有變）",
  "instalado na frente de: {0}": "已安裝在前面：{0}",
  "o comando menciona o tap, mas não no formato esperado; confira à mão": "指令中提到 tap，但格式不符預期；請手動檢查",
  "statusline criado pelo Habblaud removido": "已移除 Habblaud 建立的狀態列",
  "{0} dias": "{0} 天",
  "não consegui ler ({0})": "無法讀取（{0}）",
  "não é um objeto JSON; nada foi alterado": "不是 JSON 物件；未做任何變更",
  "JSON inválido; nada foi alterado": "JSON 無效；未做任何變更",
  "o arquivo mudou desde a leitura; nada foi alterado, rode o comando de novo": "讀取後檔案已變動；未做任何變更，請重新執行指令",
  "~ ~/.{0} (nome antigo) vai para ~/.habblaud (simulação: nada movido)": "~ ~/.{0}（舊名稱）會移到 ~/.habblaud（模擬：未移動任何東西）",
  " (na frente de: {0})": "（在前面：{0}）",
  " (sem statusline original)": "（沒有原本的狀態列）",
