  "nenhum uso capturado": "尚未擷取到用量",
  "Pronto. Os números aparecem no Habblaud depois da próxima resposta de cada sessão. Sessões já": "完成。每個工作階段下一次回覆後，數字就會出現在 Habblaud。已經",
  "abertas costumam recarregar o settings.json sozinhas; se o uso não aparecer, reabra a sessão.": "開啟的工作階段通常會自動重新載入 settings.json；如果用量沒出現，請重新開啟工作階段。",
  "Uso capturado em {0}. Para desfazer: npm run usage:uninstall": "用量記錄在 {0}。要復原：npm run usage:uninstall",
