  "Performance: {0}\nAcessibilidade: {1}\nBoas práticas: 100\nSEO: 100": "效能：{0}\n無障礙：{1}\n最佳做法：100\nSEO：100",
  "Servidor de desenvolvimento rodando em http://localhost:5173": "開發伺服器執行於 http://localhost:5173",
  "Processados {0} registros em {1}s": "已在 {1}s 內處理 {0} 筆紀錄",
