  "Comando rodando em segundo plano (id b{0}). Você recebe um aviso quando ele terminar.": "指令正在背景執行（id b{0}）。完成時會通知你。",
  "Tarefa em segundo plano falhou: {0}": "背景任務失敗：{0}",
