  "Deixei rodando em segundo plano: {0}. Volto assim que terminar.": "已讓它在背景執行：{0}。一完成我就回來。",
  "Os subagentes terminaram; vou juntar o que cada um encontrou.": "子代理人都完成了；我來整理每個人找到的內容。",
  "Encontrei o ponto do problema; vou ajustar agora.": "找到問題的根源了；現在就來修。",
  "Arquivo atualizado: {0}": "檔案已更新：{0}",
