  "A página explica a API com exemplos; o trecho relevante confirma o formato esperado.": "這個頁面用範例說明了 API；相關的部分確認了預期的格式。",
  "Resuma o que importa para a nossa implementação": "摘要出對我們的實作重要的部分",
  "{0}({1}/{2} concluídas)": "{0}（已完成 {1}/{2}）",
  "Lista de tarefas atualizada": "任務清單已更新",
  "Subagentes trabalhando em paralelo; os resultados chegam quando terminarem.": "子代理人正在平行工作；完成後就會回傳結果。",
  "{0}. Investigue o código de {1} e devolva um resumo curto com os arquivos envolvidos.": "{0}。調查 {1} 的程式碼，並回傳一份簡短摘要，列出相關的檔案。",
  "Aguardando você: {0}": "等待你：{0}",
