  "! nome antigo ainda registrado: {0}; npm run mod:install troca pelo habblaud": "! 仍登記著舊名稱：{0}；npm run mod:install 會把它換成 habblaud",
  "! tap de statusline antigo ainda instalado junto com o mod: npm run mod:install tira (ou npm run usage:uninstall)": "! 舊的 statusline tap 仍與 mod 同時安裝：npm run mod:install 會移除它（或用 npm run usage:uninstall）",
  "tap de statusline antigo instalado (jeito antigo; o mod o substitui)": "已安裝舊的 statusline tap（舊方式；mod 會取代它）",
  "! hook de permissão antigo ainda no settings.json junto com o plugin: os dois respondem; npm run mod:install tira (ou npm run hooks:uninstall)": "! 舊的權限 hook 仍與外掛同時存在於 settings.json：兩者都會回覆；npm run mod:install 會移除它（或用 npm run hooks:uninstall）",
