  "  ✗ settings.json: {0}; o tap e o hook antigos não foram conferidos": "  ✗ settings.json：{0}；未檢查舊的 tap 與 hook",
  "  ! disableAllHooks está ligado no settings.json desta conta: o mod não roda até você desligar": "  ! 此帳號的 settings.json 開啟了 disableAllHooks：關閉之前 mod 都不會執行",
