  "Pronto. Sessões novas do Claude Code já carregam o mod; nas que já estão abertas, rode /reload-plugins (ou": "完成。新的 Claude Code 工作階段會直接載入 mod；已開啟的工作階段請執行 /reload-plugins（或",
  "reabra a sessão). O uso de 5h/semanal chega ao Habblaud depois da próxima resposta de cada sessão.": "重新開啟工作階段）。5h/每週用量會在每個工作階段下一次回覆後送到 Habblaud。",
  "Para conferir: npm run mod:status · Para desfazer: npm run mod:uninstall": "檢查：npm run mod:status · 復原：npm run mod:uninstall",
  "Pronto. Sessões já abertas continuam com o mod até /reload-plugins (ou até reabrir a sessão).": "完成。已開啟的工作階段會保留 mod，直到執行 /reload-plugins（或重新開啟工作階段）。",
  "Para voltar ao jeito antigo (Claude Code anterior ao 2.1.287): npm run usage:install e npm run hooks:install": "要回到舊方式（2.1.287 之前的 Claude Code）：npm run usage:install 與 npm run hooks:install",
  "Habblaud em http://127.0.0.1:{0}": "Habblaud 位於 http://127.0.0.1:{0}",
  "{0}: fora do ar (o mod segue gravando o uso; os pedidos de permissão ficam só no terminal).": "{0}：未執行（mod 會繼續記錄用量；權限請求只會留在終端機）。",
  "{0}: no ar e respondendo pedidos de permissão (com alguma página aberta).": "{0}：執行中，正在處理權限請求（需開著頁面）。",
