  "Mensagens pelo escritório: ligadas (chegam às sessões abertas com o plugin {0}).": "來自辦公室的訊息：開啟（會送到裝有 {0} 外掛的已開啟工作階段）。",
  "Mensagens pelo escritório: desligadas no Habblaud (porta exposta na rede, HABBLAUD_TERMINAL=0 ou HABBLAUD_MENSAGENS=0).": "來自辦公室的訊息：Habblaud 中已關閉（連接埠暴露在網路上、HABBLAUD_TERMINAL=0 或 HABBLAUD_MENSAGENS=0）。",
