  // scripts/codex-bridge.ts
  "Uso: npm run codex:bridge [-- opções]\n\nEntrega as mensagens do escritório às sessões do Codex quando o Habblaud roda no Docker (deixe rodando no computador).\n\nOpções:\n  --port <n>   porta do Habblaud (padrão: HABBLAUD_PORT ou {0})\n  --once       faz uma rodada só e sai\n  -h, --help   mostra esta ajuda\n\nBinário do Codex: HABBLAUD_CODEX_BIN ou `codex` do PATH.": "用法：npm run codex:bridge [-- 選項]\n\n在 Habblaud 於 Docker 中執行時，把辦公室的訊息送到 Codex 工作階段（請讓它在電腦上持續執行）。\n\n選項：\n  --port <n>   Habblaud 連接埠（預設：HABBLAUD_PORT 或 {0}）\n  --once       只執行一輪就結束\n  -h, --help   顯示此說明\n\nCodex 執行檔：HABBLAUD_CODEX_BIN 或 PATH 中的 `codex`。",
  "--port precisa de um número entre 1 e 65535.": "--port 需要介於 1 到 65535 之間的數字。",
  "opção desconhecida: {0}\n\n{1}": "未知的選項：{0}\n\n{1}",
