  "✓ agente novo aberto no app do Claude em {0} com {1} anexos (não rodou sozinho: {2})": "✓ {0} 中的新代理人已在 Claude app 開啟，附帶 {1} 個附件（沒有自動執行：{2}）",
  "✓ agente novo aberto no app do Claude em {0} com 1 anexo (não rodou sozinho: {1})": "✓ {0} 中的新代理人已在 Claude app 開啟，附帶 1 個附件（沒有自動執行：{1}）",
  "✓ agente novo aberto no app do Claude em {0}": "✓ {0} 中的新代理人已在 Claude app 開啟",
  "✓ agente novo aberto no app do Claude em {0} com {1} anexos": "✓ {0} 中的新代理人已在 Claude app 開啟，附帶 {1} 個附件",
  "✓ agente novo aberto no app do Claude em {0} com 1 anexo": "✓ {0} 中的新代理人已在 Claude app 開啟，附帶 1 個附件",
  "pedido inválido": "無效的請求",
  "✗ agente novo recusado: {0}": "✗ 新代理人遭拒：{0}",
  "✗ agente novo em {0}: {1}": "✗ {0} 中的新代理人：{1}",
  "✓ ditado transcrito ({0}, {1} s)": "✓ 聽寫已轉錄（{0}，{1} 秒）",
