  "✗ arquivo de entrega recusado: {0}": "✗ 交付檔案遭拒：{0}",
  "Entregando as mensagens do Habblaud (http://127.0.0.1:{0}) às sessões do Codex com {1}, e começando os agentes novos pedidos no escritório. Ctrl+C para parar.": "正在把 Habblaud 訊息（http://127.0.0.1:{0}）以 {1} 送到 Codex 工作階段，並啟動辦公室中要求的新代理人。按 Ctrl+C 停止。",
  "Sem o Codex (codex no PATH ou HABBLAUD_CODEX_BIN): só começo os agentes novos pedidos no Habblaud (http://127.0.0.1:{0}). Ctrl+C para parar.": "沒有 Codex（PATH 中的 codex 或 HABBLAUD_CODEX_BIN）：只會啟動 Habblaud（http://127.0.0.1:{0}）中要求的新代理人。按 Ctrl+C 停止。",
  "Agentes novos rodam em segundo plano com {0} --bg (pasta confiável; senão, no app do Claude).": "新代理人會以 {0} --bg 在背景執行（受信任的資料夾；否則在 Claude app 中）。",
  "Sem o claude no PATH (ou HABBLAUD_CLAUDE_BIN): agentes novos abrem no app do Claude e esperam o Enter.": "PATH 中沒有 claude（或 HABBLAUD_CLAUDE_BIN）：新代理人會在 Claude app 開啟並等待按下 Enter。",
