  // scripts/hooks-install.ts
  "Aguardando resposta no Habblaud": "正在等待 Habblaud 中的回覆",
  "Uso: npm run hooks:<install|uninstall|status> [-- opções]\n\n  install     acrescenta o hook de permissão do Habblaud em cada conta (faz backup do settings.json)\n  uninstall   tira o hook do Habblaud de cada conta (os outros hooks ficam)\n  status      mostra se o hook está instalado e se o Habblaud está respondendo pedidos\n\nOpções:\n  --dry-run        mostra o que mudaria, sem gravar nada\n  --node <cmd>     comando do node usado no hook (padrão: detectado no PATH)\n  --port <n>       porta do Habblaud (padrão: HABBLAUD_PORT ou {0})\n  --timeout <s>    quanto o hook espera sua resposta no Habblaud antes de devolver o pedido ao terminal\n                   (padrão: {1} s)\n  -h, --help       mostra esta ajuda\n\nContas: as mesmas do servidor (~/.claude* com projects/ ou sessions/, CLAUDE_CONFIG_DIR ou\nHABBLAUD_CLAUDE_DIRS).": "用法：npm run hooks:<install|uninstall|status> [-- 選項]\n\n  install     為每個帳號加入 Habblaud 權限 hook（會備份 settings.json）\n  uninstall   從每個帳號移除 Habblaud 的 hook（其他 hooks 會保留）\n  status      顯示 hook 是否已安裝，以及 Habblaud 是否正在處理請求\n\n選項：\n  --dry-run        顯示會變更什麼，但不寫入任何東西\n  --node <cmd>     hook 使用的 node 指令（預設：從 PATH 偵測）\n  --port <n>       Habblaud 連接埠（預設：HABBLAUD_PORT 或 {0}）\n  --timeout <s>    hook 在 Habblaud 等你回覆多久，之後把請求交還給終端機\n                   （預設：{1} 秒）\n  -h, --help       顯示此說明\n\n帳號：與伺服器相同（含 projects/ 或 sessions/ 的 ~/.claude*、CLAUDE_CONFIG_DIR 或\nHABBLAUD_CLAUDE_DIRS）。",
  "atualizado (novo caminho do Habblaud, do node ou das opções)": "已更新（新的 Habblaud 路徑、node 路徑或選項）",
  "instalado": "已安裝",
  "hook do Habblaud removido": "已移除 Habblaud 的 hook",
  "--node precisa de um caminho.": "--node 需要路徑。",
  "--timeout precisa de um número de segundos entre 5 e 86400 (24 h).": "--timeout 需要介於 5 到 86400（24 小時）之間的秒數。",
  "Nenhuma conta do Claude Code encontrada (~/.claude* com projects/ ou sessions/). Use HABBLAUD_CLAUDE_DIRS se estiverem em outro lugar.": "找不到 Claude Code 帳號（含 projects/ 或 sessions/ 的 ~/.claude*）。如果在其他位置，請使用 HABBLAUD_CLAUDE_DIRS。",
  " (esse arquivo não existe mais: o hook falha e vale só o terminal)": " （該檔案已不存在：hook 會失敗，只有終端機有效）",
  "! {0}: o hook aponta para {1}{2}; rode npm run hooks:install para atualizar": "! {0}：hook 指向 {1}{2}；請執行 npm run hooks:install 更新",
  "• {0}: instalado ({1}; tempo limite {2} s)": "• {0}：已安裝（{1}；逾時 {2} 秒）",
  "Habblaud em http://127.0.0.1:{0}: fora do ar (com ele parado, o hook sai na hora e o terminal segue normal).": "Habblaud 位於 http://127.0.0.1:{0}：未執行（停止期間 hook 會立刻結束，終端機照常運作）。",
  "Habblaud em http://127.0.0.1:{0}: respondendo pedidos de permissão (com alguma página aberta).": "Habblaud 位於 http://127.0.0.1:{0}：正在處理權限請求（需開著頁面）。",
  "Habblaud em http://127.0.0.1:{0}: no ar, mas responder pelo escritório está desligado (porta exposta na rede ou HABBLAUD_TERMINAL=0).": "Habblaud 位於 http://127.0.0.1:{0}：執行中，但已關閉從辦公室回覆（連接埠暴露在網路上或 HABBLAUD_TERMINAL=0）。",
  "Pronto. Com o Habblaud aberto no navegador, os pedidos de permissão aparecem no escritório e você": "完成。在瀏覽器開著 Habblaud 時，權限請求會出現在辦公室中，你",
  "pode aprovar ou recusar por lá; o diálogo continua no terminal e vale o que responder primeiro.": "可以在那裡允許或拒絕；對話框仍會留在終端機，以最先送出的回覆為準。",
  "Sessões abertas costumam recarregar o settings.json sozinhas; se não, reabra a sessão.": "已開啟的工作階段通常會自動重新載入 settings.json；如果沒有，請重新開啟工作階段。",
  "Para desfazer: npm run hooks:uninstall": "復原：npm run hooks:uninstall",
