  // scripts/remote-setup.ts
  "Uso: npm run remote:setup [-- opções]\n\nLiga o acesso pelo celular (https://<nome>.local) com usuário, senha e HTTPS.\n\n  --user <nome>        usuário do login (padrão: o seu usuário do sistema)\n  --name <nome>        endereço <nome>.local (padrão: habblaud)\n  --domain <endereço>  endereço próprio, ex.: meuclaude.home (precisa de uma entrada no DNS do roteador)\n  --port <n>           porta no computador (padrão: 443 se estiver livre, senão 4748)\n  --allow <lista>      o que o celular pode fazer: permissions, messages, terminal, spawn, none (padrão: permissions)\n  --password-stdin     lê a senha da entrada padrão (automação), em vez de perguntar\n  --no-service         não instala o serviço do anúncio <nome>.local (rode npm run remote:mdns você mesmo)\n  --off                desliga o acesso pelo celular (tira as linhas do .env e o serviço; mantém a CA)": "用法：npm run remote:setup [-- 選項]\n\n開啟手機存取（https://<name>.local），使用帳號、密碼與 HTTPS。\n\n  --user <name>        登入帳號（預設：你的系統使用者名稱）\n  --name <name>        位址 <name>.local（預設：habblaud）\n  --domain <address>   自訂位址，例如 myclaude.home（需要在路由器的 DNS 中新增紀錄）\n  --port <n>           電腦上的連接埠（預設：443 若未被占用，否則 4748）\n  --allow <list>       手機可以做的事：permissions、messages、terminal、spawn、none（預設：permissions）\n  --password-stdin     從標準輸入讀取密碼（自動化用），而不是詢問\n  --no-service         不安裝 <name>.local 廣播服務（請自行執行 npm run remote:mdns）\n  --off                關閉手機存取（從 .env 移除相關設定與服務；保留 CA）",
  "falta o valor de {0}": "{0} 缺少值",
  "opção desconhecida: {0}": "未知的選項：{0}",
  "porta inválida": "連接埠無效",
  "use pelo menos {0} caracteres": "請至少使用 {0} 個字元",
  "sem espaços no começo ou no fim": "開頭或結尾不能有空格",
  "a senha não pode ser o usuário": "密碼不能和帳號相同",
  "sem terminal para perguntar a senha: use --password-stdin": "沒有終端機可以詢問密碼：請使用 --password-stdin",
  "serviço {0} ligado (log: ~/.habblaud/logs/remote-mdns.log)": "服務 {0} 已啟用（記錄：~/.habblaud/logs/remote-mdns.log）",
  "não consegui ligar o serviço: {0}": "無法啟用服務：{0}",
  "Habblaud: anuncia o endereço .local do acesso pelo celular": "Habblaud：廣播手機存取用的 .local 位址",
  "serviço habblaud-remote-mdns ligado (para seguir ligado sem login: loginctl enable-linger)": "habblaud-remote-mdns 服務已啟用（若要登出後仍保持運作：loginctl enable-linger）",
  "{0}: sem serviço automático; deixe npm run remote:mdns rodando ou use o IP": "{0}：沒有自動服務；請讓 npm run remote:mdns 持續執行，或改用 IP",
  "[remote-setup] Acesso pelo celular desligado (a CA continua em ~/.habblaud/remote-tls). Agora: npm run docker:up": "[remote-setup] 已關閉手機存取（CA 保留在 ~/.habblaud/remote-tls）。接下來：npm run docker:up",
  "Usuário do login": "登入帳號",
  "usuário inválido (sem espaços)": "帳號無效（不能有空格）",
  "senha recusada: {0}": "密碼遭拒絕：{0}",
  "Senha ({0}+ caracteres; não aparece enquanto você digita)": "密碼（{0} 個字元以上；輸入時不會顯示）",
  "Repita a senha": "再輸入一次密碼",
  "  as duas não batem; de novo.": "  兩次不一致；請再試一次。",
  "Nome do endereço (vira <nome>.local)": "位址名稱（會變成 <name>.local）",
  "nome inválido: \"{0}\" (letras, números e hífen)": "名稱無效：\"{0}\"（字母、數字與連字號）",
  "Endereço próprio, opcional (ex.: meuclaude.home; Enter pula)": "自訂位址，可選填（例如 myclaude.home；按 Enter 略過）",
  "endereço inválido: \"{0}\"": "位址無效：\"{0}\"",
  "[remote-setup] Gerando o hash da senha…": "[remote-setup] 正在產生密碼雜湊…",
  "serviço não instalado (--no-service): rode npm run remote:mdns": "未安裝服務（--no-service）：請執行 npm run remote:mdns",
  " CA local nova (o endereço mudou ou a anterior não tinha restrição de nomes): instale o certificado de novo no celular.": " 新的本機 CA（位址已變更，或先前的 CA 沒有名稱限制）：請在手機上重新安裝憑證。",
  " CA local criada.": " 已建立本機 CA。",
  "   (ou {0})": "   （或 {0}）",
