  "  Primeira vez: aceite o aviso, toque em \"Instale o certificado do Habblaud\" e confie nele": "  第一次：接受警告，點「安裝 Habblaud 憑證」並信任它",
  "    iPhone:  Ajustes > Perfil Baixado > Instalar; depois Ajustes > Geral > Sobre > Ajustes de Confiança de Certificados": "    iPhone：  設定 > 已下載描述檔 > 安裝；接著 設定 > 一般 > 關於本機 > 憑證信任設定",
  "    Android: Configurações > Segurança > Criptografia e credenciais > Instalar certificado > Certificado de CA": "    Android：設定 > 安全性 > 加密與憑證 > 安裝憑證 > CA 憑證",
  "  Impressão digital da CA (confira no celular antes de confiar):": "  CA 指紋（信任前請在手機上核對）：",
  "(indisponível)": "（無法取得）",
